  for(const label of g.labels){c.globalAlpha=Math.max(0,1-label.age/.8);this.text(label.text,label.x,label.y-14,11,'#a4f2d7','center');c.globalAlpha=1;}this.ship(g,t,input);
  for(const p of g.pulses){c.globalAlpha=Math.max(0,1-p.age/.65);this.circle(p.x,p.y,p.r,null,'#b9f4ff',3);this.circle(p.x,p.y,p.r*.85,null,'#7fcddd',1);c.globalAlpha=1;}
